import 'package:flutter/foundation.dart';
import 'package:path_provider/path_provider.dart';
import 'package:path/path.dart' as p;

import '../models/document_chunk.dart';
import '../services/backend_service.dart';
// Generated by: flutter pub run build_runner build
// Run that command once after the first `flutter pub get`.
import '../objectbox.g.dart';

/// Singleton service wrapping the ObjectBox [Store].
///
/// Stores document chunks with 384-dim embeddings from all-MiniLM-L6-v2.
/// Uses HNSW index for approximate nearest-neighbor vector search.
///
/// Usage:
/// ```dart
/// final obs = await ObjectBoxService.create();
/// ```
class ObjectBoxService {
  late final Store _store;
  late final Box<DocumentChunk> _box;

  ObjectBoxService._();

  /// Opens (or creates) the ObjectBox store in the app-documents directory.
  static Future<ObjectBoxService> create() async {
    final svc = ObjectBoxService._();
    final docsDir = await getApplicationDocumentsDirectory();
    final dbDir = p.join(docsDir.path, 'objectbox');
    svc._store = await openStore(directory: dbDir);
    svc._box = svc._store.box<DocumentChunk>();
    return svc;
  }

  // ───────────────────────────── Write ────────────────────────────────────

  /// Replaces the entire knowledge base with pre-embedded chunks from the
  /// backend's POST /embed response.
  ///
  /// Each [EmbedChunk] contains the text and its 384-dim embedding vector.
  void replaceChunksFromEmbedResponse(List<EmbedChunk> embedChunks) {
    _box.removeAll();
    final entities = embedChunks
        .where((c) => c.text.trim().length > 10)
        .map((c) => DocumentChunk(text: c.text.trim(), embedding: c.embedding))
        .toList();
    _box.putMany(entities);
    debugPrint('[OBX] Stored ${entities.length} chunks with embeddings');
  }

  /// Clears all stored chunks.
  void clearAll() => _box.removeAll();

  // ───────────────────────────── Read (Vector Search) ────────────────────

  /// Returns up to [limit] chunks whose embeddings are nearest to [queryEmbedding].
  ///
  /// Uses ObjectBox HNSW index for fast approximate nearest-neighbor search
  /// with cosine distance. Results above [_scoreThreshold] are discarded to
  /// avoid injecting irrelevant context. Also pulls immediate neighbor chunks
  /// (by stored order) to preserve context that spans chunk boundaries.
  ///
  /// [queryEmbedding] must be a 384-dim float vector (from the on-device
  /// ONNX embedding model).
  /// Maximum cosine distance for a chunk to be considered relevant.
  /// ObjectBox cosine distance: 0.0 = identical, 2.0 = opposite.
  /// 0.5 keeps only chunks that are meaningfully similar to the query.
  static const double _scoreThreshold = 0.6;

  List<String> searchByVector(List<double> queryEmbedding, {int limit = 5}) {
    final totalChunks = _box.count();
    if (totalChunks == 0) return [];

    // Use HNSW nearest-neighbor query
    final query = _box
        .query(
          DocumentChunk_.embedding.nearestNeighborsF32(queryEmbedding, limit),
        )
        .build();

    try {
      final results = query.findWithScores();
      if (results.isEmpty) {
        // Fallback: return first few chunks if no embeddings match
        return _box.getAll().take(limit).map((e) => e.text).toList();
      }

      debugPrint(
        '[OBX] HNSW search returned ${results.length} results (before filtering)',
      );
      for (final r in results) {
        debugPrint(
          '[OBX]   id=${r.object.id}, score=${r.score.toStringAsFixed(4)}, '
          'text="${r.object.text.substring(0, r.object.text.length < 60 ? r.object.text.length : 60)}..."',
        );
      }

      // Filter out chunks with weak similarity (high cosine distance)
      final filtered = results
          .where((r) => r.score <= _scoreThreshold)
          .toList();
      debugPrint(
        '[OBX] After score threshold ($_scoreThreshold): ${filtered.length}/${results.length} kept',
      );

      if (filtered.isEmpty) {
        // All results were below threshold — fall back to the single best hit
        debugPrint('[OBX] No results passed threshold, using best hit only');
        return [results.first.object.text];
      }

      // Collect hit IDs and find their indices in stored order for neighbor retrieval
      final all = _box.getAll();
      final idToIndex = <int, int>{};
      for (int i = 0; i < all.length; i++) {
        idToIndex[all[i].id] = i;
      }

      // Gather top hits + their immediate neighbors
      final selected = <int>{};
      for (final r in filtered) {
        final idx = idToIndex[r.object.id];
        if (idx == null) continue;
        selected.add(idx);
        if (idx > 0) selected.add(idx - 1);
        if (idx < all.length - 1) selected.add(idx + 1);
      }

      // Cap to limit, keeping highest-scoring if neighbors pushed us over
      var sorted = selected.toList()..sort();
      if (sorted.length > limit) {
        // Re-score by HNSW distance (lower = better for cosine)
        final hitIds = {for (final r in filtered) r.object.id: r.score};
        sorted.sort((a, b) {
          final scoreA = hitIds[all[a].id] ?? double.infinity;
          final scoreB = hitIds[all[b].id] ?? double.infinity;
          return scoreA.compareTo(scoreB);
        });
        sorted = sorted.take(limit).toList()..sort();
      }

      return sorted.map((i) => all[i].text).toList();
    } finally {
      query.close();
    }
  }

  /// Total number of stored chunks.
  int get count => _box.count();

  /// Whether stored chunks have embeddings (checks first chunk).
  bool get hasEmbeddings {
    if (_box.count() == 0) return false;
    final first = _box.getAll().first;
    return first.embedding != null && first.embedding!.isNotEmpty;
  }

  /// Returns the first [n] chunk texts for preview purposes.
  List<String> getSampleChunks({int n = 3}) {
    return _box.getAll().take(n).map((e) => e.text).toList();
  }

  /// Returns ALL chunk texts in stored order.
  List<String> getAllChunks() {
    return _box.getAll().map((e) => e.text).toList();
  }

  // ───────────────────────────── Lifecycle ────────────────────────────────

  void close() => _store.close();
}
